const input = $input.first().json;
const body = input.body || input;
const { id, estado, estado_motivo, resumen, disponibilidad, tags, proxima_cita, notas } = body;

const idNum = parseInt(String(id).replace(/[^0-9]/g, ''), 10);
if (!idNum) {
  throw new Error('Falta el campo requerido: id (número devuelto por create-lead)');
}

const isValid = (v) => v !== undefined && v !== null && String(v).trim() !== '' &&
  !['sin definir', 'null', 'undefined'].includes(String(v).trim().toLowerCase());
const toSql = (v) => `'${String(v).trim().replace(/'/g, "''")}'`;

// La tabla leads solo acepta estos estados (CHECK leads_estado_check)
const ESTADOS = ['NUEVO', 'FRIO', 'TIBIO', 'CALIENTE'];
const estadoNorm = isValid(estado)
  ? String(estado).trim().toUpperCase().replace('FRÍO', 'FRIO')
  : null;

const updates = [];
if (estadoNorm && ESTADOS.includes(estadoNorm)) updates.push(`estado = '${estadoNorm}'`);
if (isValid(estado_motivo)) updates.push(`estado_motivo = ${toSql(estado_motivo)}`);
if (isValid(resumen)) updates.push(`resumen = ${toSql(resumen)}`);
if (isValid(disponibilidad)) updates.push(`disponibilidad = ${toSql(disponibilidad)}`);
if (isValid(tags)) updates.push(`tags = ${toSql(tags)}`);
if (isValid(proxima_cita)) {
  const d = new Date(String(proxima_cita));
  if (!isNaN(d.getTime())) updates.push(`proxima_cita = '${d.toISOString()}'::timestamptz`);
}
if (isValid(notas)) updates.push(`notas = ${toSql(notas)}`);

updates.push('estado_fecha = CURRENT_TIMESTAMP');
updates.push('ultimo_contacto = CURRENT_TIMESTAMP');
updates.push('updated_at = CURRENT_TIMESTAMP');

const query = `WITH ant AS (SELECT estado AS estado_anterior FROM leads WHERE id = ${idNum}) UPDATE leads SET ${updates.join(', ')} WHERE id = ${idNum} RETURNING id, nombre, whatsapp, estado, estado_motivo, updated_at, lead_tipo, origen, nivel, resumen, disponibilidad, (SELECT estado_anterior FROM ant) AS estado_anterior, (SELECT valor FROM academia_config WHERE clave = 'telegram_chat_id_avisos') AS chat_id;`;

return [{ json: { query } }];

const result = $('PostgreSQL - Update').first().json;

if (!result || !result.id) {
  return [{json: {success: false, message: 'Lead no encontrado'}}];
}

return [{json: {success: true, message: 'Lead actualizado correctamente', lead: {id: result.id, nombre: result.nombre, estado: result.estado, estado_motivo: result.estado_motivo}}}];

const r = $input.first().json;
const h = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Solo avisa cuando el lead PASA a CALIENTE (no en cada actualización)
const enviar = !!r && r.estado === 'CALIENTE' && r.estado_anterior !== 'CALIENTE' && !!r.chat_id;

const lineas = [
  '🔥 <b>Lead CALIENTE</b>',
  '',
  `👤 ${h(r.nombre || 'Sin nombre')}${r.lead_tipo ? ' · ' + h(r.lead_tipo) : ''}`,
  `📱 ${h(r.whatsapp)}`
];
if (r.origen) lineas.push(`📣 Origen: ${h(r.origen)}`);
if (r.nivel) lineas.push(`🎯 Nivel: ${h(r.nivel)}`);
if (r.disponibilidad) lineas.push(`🕒 ${h(r.disponibilidad)}`);
if (r.estado_motivo) lineas.push('', `💬 ${h(r.estado_motivo)}`);
if (r.resumen) lineas.push('', h(String(r.resumen).slice(0, 400)));

return [{ json: { enviar, chat_id: r.chat_id, texto: lineas.join('\n') } }];
